#!/usr/bin/env python3
from pathlib import Path
import base64, gzip, re, shutil

ROOT = Path(__file__).resolve().parents[1]
PACK = ROOT / "feature_231/default_audio_pack.zip"
PAYLOAD = {'app/src/main/java/vn/com/vhb/qmsdisplay/MainActivity.java': '[... ELLIPSIZATION ...]', 'app/src/main/assets/qms_audio_bridge/manifest.json': '', 'app/src/main/assets/qms_audio_bridge/content.js': '', 'VERSION.txt': ''}

main = ROOT / "app/src/main/java/vn/com/vhb/qmsdisplay/MainActivity.java"
build = ROOT / "app/build.gradle"
settings = ROOT / "settings.gradle"
if not main.is_file() or not build.is_file() or not PACK.is_file():
    raise SystemExit("2.2.10 baseline/default audio pack not found")
main_text = main.read_text(encoding="utf-8")
build_text = build.read_text(encoding="utf-8")
if 'private static final String VERSION = "2.2.10";' not in main_text:
    raise SystemExit("apply_231 requires flattened VHB QMS Android Display 2.2.10 MainActivity")
if "versionName '2.2.10'" not in build_text or "versionCode 2021000" not in build_text:
    raise SystemExit("apply_231 requires app/build.gradle version 2.2.10 / 2021000")

for rel, encoded in PAYLOAD.items():
    target = ROOT / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(gzip.decompress(base64.b64decode(encoded)))

audio = ROOT / "app/src/main/assets/audio"
audio.mkdir(parents=True, exist_ok=True)
shutil.copy2(PACK, audio / "default_audio_pack.zip")

build_text = build_text.replace("versionCode 2021000", "versionCode 2031000")
build_text = build_text.replace("versionName '2.2.10'", "versionName '2.3.1'")
build.write_text(build_text, encoding="utf-8")
if settings.is_file():
    s = settings.read_text(encoding="utf-8")
    s = re.sub(r'rootProject\.name\s*=\s*"[^"]+"', 'rootProject.name = "VHB_QMS_Android_Display_2.3.1_GeckoView"', s)
    settings.write_text(s, encoding="utf-8")
orig = ROOT / "app/src/main/java/vn/com/vhb/qmsdisplay/MainActivity.java.orig"
if orig.exists(): orig.unlink()
print("Applied VHB QMS Android Display 2.3.1 Audio File Engine")
